def check_starting_points(N):
    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            # Row-major filling
            grid[r][c] = r * N + c + 1

    starts = []
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for r in range(N):
        for c in range(N):
            current_value = grid[r][c]
            is_start = True

            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                # Check bounds
                if 0 <= nr < N and 0 <= nc < N:
                    neighbor_value = grid[nr][nc]

                    # Condition (i): Must only be adjacent to fields with larger numbers
                    if neighbor_value <= current_value:
                        is_start = False
                        break

            if is_start:
                starts.append((r, c, current_value))

    return starts

